import{_ as t,o,c as a,a2 as i}from"./chunks/framework.DHmNT4rz.js";const g=JSON.parse('{"title":"Vite Plus (Vite+)","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/vite-plus.md","filePath":"develop/vite-plus.md","lastUpdated":null}'),n={name:"develop/vite-plus.md"};function r(d,e,s,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/vite-plus.md" target="_blank" rel="noreferrer"><code>.agents/vite-plus.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="vite-plus-vite" tabindex="-1">Vite Plus (Vite+) <a class="header-anchor" href="#vite-plus-vite" aria-label="Permalink to &quot;Vite Plus (Vite+)&quot;">​</a></h1><h2 id="what-it-is" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What It Is&quot;">​</a></h2><p>Vite Plus is the all-in-one CLI that replaces pnpm/npm/yarn <strong>and</strong> bundles Oxlint, Oxfmt, Vitest, and staging hooks into a single <code>defineConfig</code> in the root <code>vite.config.ts</code>.</p><h2 id="cli-mapping" tabindex="-1">CLI Mapping <a class="header-anchor" href="#cli-mapping" aria-label="Permalink to &quot;CLI Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Instead of</th><th>Use</th></tr></thead><tbody><tr><td><code>pnpm</code> / <code>npm</code> / <code>yarn</code></td><td><code>vp</code></td></tr><tr><td><code>pnpx</code> / <code>npx</code></td><td><code>vpx</code></td></tr><tr><td><code>pnpm run &lt;script&gt;</code></td><td><code>vp run &lt;script&gt;</code></td></tr><tr><td><code>pnpm run -w &lt;script&gt;</code></td><td><code>vp run -w &lt;script&gt;</code> (workspace root)</td></tr><tr><td><code>pnpm --filter &lt;pkg&gt; &lt;script&gt;</code></td><td><code>vp run --filter &lt;pkg&gt; &lt;script&gt;</code></td></tr><tr><td><code>pnpm add &lt;dep&gt;</code></td><td><code>vp add &lt;dep&gt;</code></td></tr><tr><td><code>npx &lt;pkg&gt;</code></td><td><code>vpx &lt;pkg&gt;</code></td></tr></tbody></table><h2 id="key-behaviors" tabindex="-1">Key Behaviors <a class="header-anchor" href="#key-behaviors" aria-label="Permalink to &quot;Key Behaviors&quot;">​</a></h2><ul><li><code>vp run -r &lt;script&gt;</code> — runs script recursively across all packages</li><li><code>vp check</code> — verify formatting, lint, and types</li><li><code>vp check --fix</code> — write formatting/fixes, then lint and typecheck (auto-runs on staged files via hooks)</li><li><code>vp test --coverage --run</code> — package-local Vitest coverage run</li><li><code>vp config</code> — sets up Vite Plus hooks (runs on <code>prepare</code>)</li><li><code>vp env doctor</code> — checks the environment for potential issues, use when environment config seems wrong.</li></ul><p>Use <code>vp check --fix</code> as the normal cleanup and validation command after code or configuration edits. Prefer the package-local command for scoped work, and use the workspace command from <a href="/SaaSWeave/develop/workflow">Workflow</a> when changes span packages, generated artifacts, or root configuration. Use <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/choice-flows.md" target="_blank" rel="noreferrer">Choice flows</a> only when a human decision is needed, such as selecting a validation scope for broad work or approving a permission-sensitive command.</p><h2 id="root-vite-config-ts" tabindex="-1">Root <code>vite.config.ts</code> <a class="header-anchor" href="#root-vite-config-ts" aria-label="Permalink to &quot;Root `vite.config.ts`&quot;">​</a></h2><p>Contains the unified config for:</p><ul><li><strong>Staged hooks</strong>: <code>&quot;*&quot;: &quot;vp check --fix&quot;</code> — auto-formats + lints on commit</li><li><strong>Vitest</strong>: test includes, global config</li><li><strong>Oxfmt</strong>: ignore patterns, import sorting (by FSD layer), Tailwind class sorting</li><li><strong>Oxlint</strong>: ESLint plugin integration (<code>eslint-plugin-fsd-lint</code>, <code>@tanstack/eslint-plugin-query</code>, <code>eslint-plugin-react-hooks</code>)</li></ul><h2 id="mental-model" tabindex="-1">Mental Model <a class="header-anchor" href="#mental-model" aria-label="Permalink to &quot;Mental Model&quot;">​</a></h2><p>Think of <code>vp</code> as the <strong>only CLI you need</strong> for this project. It wraps pnpm for package management and Vite&#39;s ecosystem for build/lint/format/test. Never install or invoke pnpm/npm/yarn directly for standard development.</p>',14)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
